async function getArtifactsForBranchAndWorkflow(octokit2, { owner: owner2, repo: repo2, workflow_id, branch, commit, artifactName }) {
  core2.startGroup(
    `getArtifactsForBranchAndWorkflow - workflow:"${workflow_id}",  branch:"${branch}"${commit ? `,  commit:"${commit}"` : ""}`
  );
  let currentPage = 0;
  let completedWorkflowRuns = [];
  for await (const response of octokit2.paginate.iterator(octokit2.actions.listWorkflowRuns, {
    owner: owner2,
    repo: repo2,
    // Below is typed incorrectly, it needs to be a string but typed as number
    workflow_id,
    // XXX: GH broke filtering so we have to do it client-side for now
    // branch,
    // status: 'success',
    per_page: PER_PAGE_LIMIT
  })) {
    const data = response.data;
    if (!data.length) {
      core2.warning(`Workflow ${workflow_id} not found in branch ${branch}`);
      core2.endGroup();
      return null;
    }
    const workflowRuns = data.filter((workflowRun) => workflowRun.head_repository.full_name === `${owner2}/${repo2}`).filter(
      // branch and status are temp due to GH issues Note, the GH api accepts
      // both `status` and `conclusion` field values
      // https://octokit.github.io/rest.js/v18#actions-list-workflow-workflowRuns-for-repo
      // but we are only interested in successful workflowRuns (which means we
      // have to use `conclusion`)
      (workflowRun) => workflowRun.head_branch === branch && workflowRun.conclusion === "success"
    );
    const workflowRunsForCommit = commit ? workflowRuns.filter((run2) => run2.head_sha === commit) : workflowRuns;
    if (workflowRunsForCommit.length) {
      completedWorkflowRuns = completedWorkflowRuns.concat(workflowRunsForCommit);
      break;
    }
    if (currentPage > MAX_PAGES) {
      core2.warning(`Workflow ${workflow_id} not found in branch: ${branch}${commit ? ` and commit: ${commit}` : ""}`);
      core2.endGroup();
      return null;
    }
    currentPage++;
  }
  for (const workflowRun of completedWorkflowRuns) {
    core2.debug(`Checking artifacts for workflow run: ${workflowRun.html_url}`);
    const {
      data: { artifacts }
    } = await octokit2.actions.listWorkflowRunArtifacts({
      owner: owner2,
      repo: repo2,
      run_id: workflowRun.id
    });
    if (!artifacts) {
      core2.debug(
        `Unable to fetch artifacts for branch: ${branch}, workflow: ${workflow_id}, workflowRunId: ${workflowRun.id}`
      );
    } else {
      const foundArtifact = artifacts.find(({ name }) => name === artifactName);
      if (foundArtifact) {
        core2.debug(`Found suitable artifact: ${foundArtifact.url}`);
        core2.endGroup();
        return {
          artifact: foundArtifact,
          workflowRun
        };
      }
    }
  }
  core2.warning(`Artifact not found: ${artifactName}`);
  core2.endGroup();
  return null;
}

